/** Stores a merge of one person into another on the sheet (see #merge). */
@Repository
public class PersonMerger {

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public PersonMerger(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /**
     * Merges {@code from} into {@code into}: from's claims move to into (numbers and dates kept, listed after every claim
     * on the sheet in the order they were added, each unbound from any statement figure); from's name and aliases become
     * into's aliases; from's patrons are added to into's (not into themselves, no repeats) and anyone naming from as
     * patron names into instead (no repeats; into never their own patron); from's pool memberships move to into (shares
     * added where into is already a member). From's statements, holds, watchers, contact and grades are dropped, and from
     * leaves the sheet (kept, as they stood, only for reading the sheet as of a date before the merge).
     */
    public void merge(String sheetId, Person from, Person into) {
        long f = from.id();
        long t = into.id();
        List<Long> claims = jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed, id",
                Long.class, sheetId, f);
        for (Long id : claims) {
            jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, "
                    + "listed = (SELECT COALESCE(MAX(c.listed), 0) + 1 FROM claim c WHERE c.sheet_id = ?) WHERE id = ?",
                    t, sheetId, id);
        }

        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?", t, sheetId, f);

        for (Map<String, Object> p : jdbc.queryForList("SELECT patron_id, added_on FROM patron WHERE sheet_id = ? AND person_id = ?",
                sheetId, f)) {
            addPatron(sheetId, t, ((Number) p.get("patron_id")).longValue(), p.get("added_on"));
        }
        for (Map<String, Object> p : jdbc.queryForList("SELECT person_id, added_on FROM patron WHERE sheet_id = ? AND patron_id = ?",
                sheetId, f)) {
            addPatron(sheetId, ((Number) p.get("person_id")).longValue(), t, p.get("added_on"));
        }
        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, f, f);

        for (Map<String, Object> m : jdbc.queryForList("SELECT id, pool_id, share FROM pool_member WHERE person_id = ? ORDER BY id", f)) {
            long poolId = ((Number) m.get("pool_id")).longValue();
            BigDecimal share = (BigDecimal) m.get("share");
            List<Long> theirs = jdbc.queryForList("SELECT id FROM pool_member WHERE pool_id = ? AND person_id = ?", Long.class,
                    poolId, t);
            if (theirs.isEmpty()) {
                jdbc.update("UPDATE pool_member SET person_id = ? WHERE id = ?", t, m.get("id"));
            } else {
                jdbc.update("UPDATE pool_member SET share = share + ? WHERE id = ?", share, theirs.get(0));
                jdbc.update("DELETE FROM pool_member WHERE id = ?", m.get("id"));
            }
        }

        StringBuilder grades = new StringBuilder();
        for (PersonGrade g : from.grades()) {
            grades.append(grades.length() == 0 ? "" : ";").append(g.grade()).append('@').append(g.from() == null ? "" : g.from());
        }
        jdbc.update("INSERT INTO person_merged (id, sheet_id, name, grades, retired_from, terms, contact, added_on, merged_on)"
                + " SELECT id, sheet_id, name, ?, retired_from, terms, contact, added_on, ? FROM person WHERE sheet_id = ? AND id = ?",
                grades.toString(), java.sql.Date.valueOf(sheets.today(sheetId)), sheetId, f);

        for (String table : List.of("statement", "person_hold", "watch", "person_grade", "person_grade_log",
                "person_retire_log", "person_retirement", "person_terms_log")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, f);
        }
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, f);
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, added_on) VALUES (?, ?, ?, ?)", sheetId, t, from.name(),
                java.sql.Date.valueOf(sheets.today(sheetId)));
    }

    /** Names the patron for the person, unless it is themselves or they already have them. */
    private void addPatron(String sheetId, long personId, long patronId, Object addedOn) {
        if (personId == patronId) {
            return;
        }
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM patron WHERE sheet_id = ? AND person_id = ? AND patron_id = ?",
                Integer.class, sheetId, personId, patronId);
        if (n != null && n == 0) {
            jdbc.update("INSERT INTO patron (sheet_id, person_id, patron_id, added_on) VALUES (?, ?, ?, ?)", sheetId, personId,
                    patronId, addedOn);
        }
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Stores a transfer of a person to another sheet (see #transfer). */
@Repository
public class PersonTransferrer {

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;
    private final PersonRepository people;

    public PersonTransferrer(JdbcTemplate jdbc, SheetRepository sheets, PersonRepository people) {
        this.jdbc = jdbc;
        this.sheets = sheets;
        this.people = people;
    }

    /**
     * Moves the person to the other sheet with their grades (and from-dates), terms, contact and aliases, added there on
     * its today (the sheet they left kept as their origin) at the end of its list; and their claims with their status, dates, notes, tags, frozen figures, logs, comments and reminders,
     * listed there as its newest claims in the order they were listed, each unbound from any statement figure, without its
     * reference, lock or settle batch. Their statements, holds, watchers, patron links (either way), pool memberships,
     * period totals and retirement log are dropped: they leave this sheet entirely. Returns the ids of the moved claims
     * that have a number, in the order they were opened (by the sheet's today when each was opened, then as added), for
     * the caller to number on the other sheet.
     */
    public List<Long> transfer(Person person, String to) {
        String from = person.sheetId();
        long id = person.id();
        List<Long> claims = jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed, id",
                Long.class, from, id);
        List<Long> numbered = jdbc.queryForList("SELECT c.id FROM claim c WHERE c.sheet_id = ? AND c.person_id = ?"
                + " AND c.claim_number IS NOT NULL ORDER BY (SELECT MIN(l.log_date) FROM claim_log l WHERE l.sheet_id = c.sheet_id"
                + " AND l.claim_id = c.id AND l.status = 'OPEN') NULLS LAST, c.id", Long.class, from, id);
        for (Long c : claims) {
            for (String table : List.of("claim_log", "claim_reminder", "claim_comment", "claim_void_reason")) {
                jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND claim_id = ?", to, from, c);
            }
            jdbc.update("UPDATE claim_edit SET sheet_id = ?, ref = NULL WHERE sheet_id = ? AND claim_id = ?", to, from, c);
            jdbc.update("DELETE FROM claim_batch WHERE sheet_id = ? AND claim_id = ?", from, c);
            jdbc.update("UPDATE claim SET sheet_id = ?, stated = FALSE, stated_due = NULL, ref = NULL, ref_key = NULL, locked_by = NULL, "
                    + "listed = (SELECT COALESCE(MAX(x.listed), 0) + 1 FROM claim x WHERE x.sheet_id = ?) WHERE id = ?",
                    to, to, c);
        }

        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", from, id, id);
        jdbc.update("DELETE FROM pool_member WHERE person_id = ?", id);
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ?", from, id);
        for (String table : List.of("statement", "person_hold", "watch", "person_retire_log")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", from, id);
        }
        for (String table : List.of("person_grade", "person_grade_log", "person_terms_log", "person_alias", "person_retirement")) {
            jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, from, id);
        }
        jdbc.update("UPDATE person SET sheet_id = ?, added_on = ?, origin = ? WHERE sheet_id = ? AND id = ?", to,
                Date.valueOf(sheets.today(to)), from, from, id);
        people.toEnd(to, id);
        return numbered;
    }

    /**
     * Moves the person to the other sheet merged into {@code into} there, as a merge does (see PersonMerger#merge): their
     * claims go to into as transfer moves them (see #transfer), listed there after every claim of the sheet; their name
     * and aliases become into's aliases (one into already has as written is not repeated); their grades, terms, contact
     * and retirement are dropped, as is everything a transfer drops, and they leave this sheet entirely. Returns the ids
     * of the moved claims that have a number, in the order they were opened, for the caller to number on the other sheet.
     */
    public List<Long> transferInto(Person person, String to, Person into) {
        String from = person.sheetId();
        long id = person.id();
        long t = into.id();
        List<Long> claims = jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed, id",
                Long.class, from, id);
        List<Long> numbered = jdbc.queryForList("SELECT c.id FROM claim c WHERE c.sheet_id = ? AND c.person_id = ?"
                + " AND c.claim_number IS NOT NULL ORDER BY (SELECT MIN(l.log_date) FROM claim_log l WHERE l.sheet_id = c.sheet_id"
                + " AND l.claim_id = c.id AND l.status = 'OPEN') NULLS LAST, c.id", Long.class, from, id);
        for (Long c : claims) {
            for (String table : List.of("claim_log", "claim_reminder", "claim_comment", "claim_void_reason")) {
                jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND claim_id = ?", to, from, c);
            }
            jdbc.update("UPDATE claim_edit SET sheet_id = ?, ref = NULL WHERE sheet_id = ? AND claim_id = ?", to, from, c);
            jdbc.update("DELETE FROM claim_batch WHERE sheet_id = ? AND claim_id = ?", from, c);
            jdbc.update("UPDATE claim SET sheet_id = ?, person_id = ?, stated = FALSE, stated_due = NULL, ref = NULL, ref_key = NULL, "
                    + "locked_by = NULL, listed = (SELECT COALESCE(MAX(x.listed), 0) + 1 FROM claim x WHERE x.sheet_id = ?) WHERE id = ?",
                    to, t, to, c);
        }

        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", from, id, id);
        jdbc.update("DELETE FROM pool_member WHERE person_id = ?", id);
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ?", from, id);
        for (String table : List.of("statement", "person_hold", "watch", "person_retire_log", "person_grade", "person_grade_log",
                "person_terms_log", "person_retirement")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", from, id);
        }

        java.util.Set<String> held = new java.util.HashSet<>(into.aliases());
        held.add(into.name());
        for (java.util.Map<String, Object> a : jdbc.queryForList("SELECT id, alias FROM person_alias WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                from, id)) {
            if (held.add((String) a.get("alias"))) {
                jdbc.update("UPDATE person_alias SET sheet_id = ?, person_id = ? WHERE id = ?", to, t, a.get("id"));
            } else {
                jdbc.update("DELETE FROM person_alias WHERE id = ?", a.get("id"));
            }
        }
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", from, id);
        if (held.add(person.name())) {
            jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, added_on) VALUES (?, ?, ?, ?)", to, t, person.name(),
                    Date.valueOf(sheets.today(to)));
        }
        return numbered;
    }
}
