  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "terms-A", "20");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "perm-close", "clerk");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "0.40", "note": "tpl"})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "100.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00", "from": "2026-03-10"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "terms": "3", "contact": "ben@x"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "contact": " Ada@x ", "tags": "c"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "terms": "3", "tags": "a"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "33.33"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "33.33"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "33.34", "from": "2026-03-01", "to": "2026-04-30"})).toBe(true);
  const pl_ada_1 = ui.must(await ui.addPlan(pg_uma, p_ada, {"amount": "7.77", "start": "2026-02-20", "end": "2026-04-30", "every": "10"}));
  await ui.setToday(pg_uma, "2026-03-31");
  expect(await ui.editPerson(pg_uma, p_ben, {"grade": "C"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ada, {"terms": "20"})).toBe(true);
  expect(await ui.addAlias(pg_uma, p_ada, "Al")).toBe(true);
  const c_ada_0 = ui.must(await ui.claimFromTemplate(pg_uma, p_ada, "T1"));
  expect(await ui.statementAsOf(pg_uma, p_ada, "2026-02-10")).toBe(false);
  expect(await ui.addPatron(pg_uma, p_ben, "Cam")).toBe(true);
  await ui.refresh(pg_uma);
