s=s.replace('''    /** The sheet's parent sheet id, or null when it has none. */''','''    /** The sheet's pot as it was stored while the sheet's today was on or before the date, or null when it was blank
     *  (none) or not yet stored. */
    public BigDecimal pot(String sheetId, LocalDate madeOn) {
        String value = null;
        for (Setting s : storedBy(sheetId, madeOn)) {
            if (POT.equals(s.key()) && s.from() == null) {
                value = s.value();
            }
        }
        return value == null || value.isBlank() ? null : new BigDecimal(value);
    }

    /** The sheet's parent sheet id, or null when it has none. */''',1)
open(p,'w').write(s)
p='src/main/java/net/officefloor/hq/app/pool/PoolRepository.java'
s=open(p).read()
s=s.replace('''        BigDecimal pot = settings.pot(sheetId);
        LocalDate today''','''        BigDecimal pot = asOf != null ? settings.pot(sheetId, asOf) : settings.pot(sheetId);
        LocalDate today''')
s=s.replace(''' read as of a date (null: now): the date stands in for the sheet's today. */''',''' read as of a date (null: now): the date stands in for the sheet's today, and the pot is
     *  the one stored by then. */''')
open(p,'w').write(s)
EOF
grep -n 'pot(sheetId, asOf)' src/main/java/net/officefloor/hq/app/pool/PoolRepository.java; bin/e2e > .run/e2e.log 2>&1; echo $?; grep -E '✘|✓|passed|failed' .run/e2e.log
